import numpy as np
from scipy.optimize import brentq
n=150000; L=np.log(n); T=10.0; m=6; Tn=n-m-1
def kl(lq,b):
    q=np.exp(lq); t=Tn*q; h=(1-t-b)/m
    H=-(1-t-b)*np.log(h)-b*np.log(b)-t*lq
    fwd=L-H
    bwd=-L-(m*np.log(h)+np.log(b)+Tn*lq)/n
    return fwd,bwd
def solve_b(lq):
    q=np.exp(lq); t=Tn*q
    f=lambda b: kl(lq,b)[0]-T
    hi=(1-t)/(m+1)
    return brentq(f,1e-15,hi,xtol=1e-20,rtol=8.9e-16)
for lq in [-30,-28,-26,-24,-23,-22,-21,-20,-19,-18]:
    try: b=solve_b(lq); print(lq,b,kl(lq,b))
    except Exception as e: print(lq,'no',e)
